<?php ob_start(); ?><h1><?= e(t('Quarantine')) ?></h1><table><tr><th><?= e(t('ID')) ?></th><th><?= e(t('Original path')) ?></th><th><?= e(t('Quarantine path')) ?></th><th>SHA256</th><th><?= e(t('Date')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Restore')) ?></th></tr><?php foreach($items as $i): ?><tr><td><?= e($i['id']) ?></td><td><code><?= e($i['original_path']) ?></code></td><td><code><?= e($i['quarantine_path']) ?></code></td><td><?= e($i['sha256']) ?></td><td><?= e($i['created_at']) ?></td><td><?= e(t($i['status'])) ?></td><td><?php if(config('guard.web_actions_enabled') && $i['status']==='quarantined'): ?><form method="post" action="/quarantine/restore" onsubmit="return confirm(<?= e(json_encode(t('Restore quarantined file?'))) ?>)"><input type="hidden" name="id" value="<?= e($i['id']) ?>"><button class="btn"><?= e(t('Restore')) ?></button></form><?php else: ?><code>php artisan guard:restore <?= e($i['id']) ?></code><?php endif ?></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
